import { useEffect, useMemo, useState, useRef, createContext, useContext } from 'react';
import { Link, NavLink, Navigate, Route, Routes, useLocation, useNavigate, useParams, useSearchParams } from 'react-router-dom';
import { Activity, Bell, Check, ChevronDown, Circle, CircleDot, CircleHelp, ClipboardList, Clock3, Command, FilePlus2, Gauge, Headphones, LockKeyhole, LogOut, Menu, Search, ShieldCheck, Sparkles, Ticket, UserRound, X } from 'lucide-react';
import { api, send } from './api.js';

const CATEGORIES=['hardware','network','software','account-access'];
const PRIORITIES=['low','medium','high','urgent'];
const STATUSES=['open','in-progress','resolved','closed'];
const labels={hardware:'Hardware',network:'Network',software:'Software','account-access':'Account access','in-progress':'In progress',open:'Open',resolved:'Resolved',closed:'Closed',urgent:'Urgent',high:'High',medium:'Medium',low:'Low'};
const DEMO_PASSWORD='Helpdesk360!';
const DEMO_ACCOUNTS=[
  {username:'priya.nair',name:'Priya Nair',role:'Employee'},
  {username:'rahul.verma',name:'Rahul Verma',role:'Employee'},
  {username:'sana.khan',name:'Sana Khan',role:'Employee'},
  {username:'arjun.mehta',name:'Arjun Mehta',role:'Technician'},
  {username:'meera.iyer',name:'Meera Iyer',role:'Technician'},
];
const QUEUE_VIEWS=[
  {label:'All active',query:'active=1'},
  {label:'Unassigned',query:'assigned=unassigned&active=1'},
  {label:'Mine',query:'assigned=me&active=1'},
  {label:'Urgent',query:'priority=urgent&active=1'},
  {label:'Overdue',query:'overdue=1'},
  {label:'Completed',query:'status=resolved%2Cclosed'},
];
const AuthContext=createContext(null);const ToastContext=createContext(()=>{});
const useAuth=()=>useContext(AuthContext);const useToast=()=>useContext(ToastContext);
const ticketLink=(id)=>`/tickets/${id}`;
const filterLink=(filters)=>`/queue?${new URLSearchParams(Object.entries(filters).map(([key,value])=>[key,Array.isArray(value)?value.join(','):String(value)])).toString()}`;
const fmtDate=(date)=>new Intl.DateTimeFormat(undefined,{dateStyle:'medium',timeStyle:'short'}).format(new Date(date));
const relative=(date)=>{const hours=Math.max(0,Math.floor((Date.now()-Date.parse(date))/3600000));if(hours<1)return 'Just now';if(hours<24)return `${hours}h ago`;return `${Math.floor(hours/24)}d ago`;};
const fmtDuration=(hours)=>hours==null?'—':hours<1?`${Math.round(hours*60)} min`:`${hours.toFixed(1)} hr`;

function StatusBadge({status}){const icons={open:<Circle size={13}/>, 'in-progress':<CircleDot size={13}/>,resolved:<Check size={13}/>,closed:<LockKeyhole size={13}/>};return <span className={`badge status ${status}`}>{icons[status]}{labels[status]||status}</span>;}
function PriorityBadge({priority}){return <span className={`badge priority ${priority}`}>{labels[priority]||priority}</span>;}
function ErrorMessage({children}){return children?<div className="error-message" role="alert">{children}</div>:null;}
function How({children}){return <details className="how"><summary>How this is counted</summary><p>{children}</p></details>;}

export default function App(){
  const [user,setUser]=useState(null),[checking,setChecking]=useState(true),[offline,setOffline]=useState(false),[toast,setToast]=useState(null);
  useEffect(()=>{document.documentElement.dataset.theme=user?.role||'employee';},[user]);
  useEffect(()=>{api('/auth/me').then(x=>{document.documentElement.dataset.theme=x.user.role;setUser(x.user);}).catch(e=>{if(e.status===0)setOffline(true);}).finally(()=>setChecking(false));},[]);
  const notify=(message,tone='success',action=null)=>{setToast({message,tone,action});window.setTimeout(()=>setToast(null),5000)};
  if(checking)return <main className="loading-screen"><div className="spinner"/><span>Loading your workspace…</span></main>;
  return <AuthContext.Provider value={{user,setUser,offline,setOffline}}><ToastContext.Provider value={notify}>
    {offline&&<div className="offline-banner" role="alert">Can't reach the server. Check your connection and try again.</div>}
    {!user?<Routes><Route path="*" element={<Login/>}/></Routes>:<Shell/>}
    {toast&&<div className={`toast ${toast.tone}`} role="status">{toast.tone==='success'?<Check size={16}/>:<X size={16}/>} <span>{toast.message}</span>{toast.action&&<button className="toast-action" onClick={()=>{toast.action.onClick();setToast(null);}}>{toast.action.label}</button>}</div>}
  </ToastContext.Provider></AuthContext.Provider>;
}

function Login(){
  const {setUser}=useAuth(),[username,setUsername]=useState(''),[password,setPassword]=useState(''),[error,setError]=useState(''),[pending,setPending]=useState(false);
  async function authenticate(name,secret){setUsername(name);setPassword(secret);setError('');setPending(true);try{const x=await send('/auth/login','POST',{username:name,password:secret});setUser(x.user);}catch(err){setError(err.message);}finally{setPending(false);}}
  async function submit(e){e.preventDefault();await authenticate(username,password);}
  return <main className="login-wrap"><div className="login-panel panel"><div className="brand-mark"><Headphones size={24}/></div><div className="eyebrow">IT SERVICE DESK</div><h1>Welcome back</h1><p className="muted">Sign in to view and manage your support tickets.</p>
    <form className="stack-form" onSubmit={submit}><label>Username<input autoComplete="username" value={username} onChange={e=>setUsername(e.target.value)} required autoFocus/></label><label>Password<input type="password" autoComplete="current-password" value={password} onChange={e=>setPassword(e.target.value)} required/></label><ErrorMessage>{error}</ErrorMessage><button className="primary-btn full" disabled={pending}>{pending?'Signing in…':'Sign in'}</button></form>
    <details className="demo-help"><summary>Demo accounts <span className="demo-help-hint">click an account to sign in</span></summary><div className="demo-account-list">{DEMO_ACCOUNTS.map(account=><button key={account.username} className="demo-account" type="button" disabled={pending} onClick={()=>authenticate(account.username,DEMO_PASSWORD)}><span className="demo-account-name"><b>{account.name}</b><small>{account.role}</small></span><span className="demo-account-meta"><span>{account.username}</span><span>{DEMO_PASSWORD}</span></span><span className="demo-account-action">{pending?'Please wait…':'Sign in →'}</span></button>)}</div></details>
  </div><div className="login-foot">HELPDESK 360 <span>•</span> SUPPORT OPERATIONS</div></main>;
}

function LegacyShell(){
  const {user,setUser}=useAuth(),navigate=useNavigate(),location=useLocation(),[menuOpen,setMenuOpen]=useState(false),[notificationOpen,setNotificationOpen]=useState(false),[notifications,setNotifications]=useState([]),[shortcuts,setShortcuts]=useState(false);
  const technician=user.role==='technician';
  useEffect(()=>{setMenuOpen(false);},[location.pathname]);
  useEffect(()=>{api('/notifications').then(x=>setNotifications(x.items)).catch(()=>{});},[user]);
  useEffect(()=>{let prefix=false;const onKey=(e)=>{if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))return;if(e.key==='?'){setShortcuts(x=>!x);return;}if(e.key==='Escape'){setShortcuts(false);setNotificationOpen(false);setMenuOpen(false);return;}if(e.key==='/'){e.preventDefault();document.querySelector('[data-global-search]')?.focus();return;}if(e.key==='n'){navigate('/new');return;}if(e.key==='g'){prefix=true;setTimeout(()=>prefix=false,900);return;}if(prefix&&e.key==='q'&&technician)navigate('/queue');if(prefix&&e.key==='d'&&technician)navigate('/dashboard');};window.addEventListener('keydown',onKey);return()=>window.removeEventListener('keydown',onKey);},[navigate,technician]);
  async function logout(){await send('/auth/logout','POST').catch(()=>{});setUser(null);}
  async function markRead(){const ids=notifications.filter(n=>!n.read_at).map(n=>n.id);if(ids.length){await send('/notifications/read','POST',{ids}).catch(()=>{});setNotifications(ns=>ns.map(n=>({...n,read_at:n.read_at||new Date().toISOString()})));}}
  const nav=[...(technician?[['Dashboard','/dashboard',Gauge],['Queue','/queue',ClipboardList]]:[['My tickets','/my-tickets',Ticket]]),['New ticket','/new',FilePlus2]];
  return <div className="app-shell"><aside className={`sidebar ${menuOpen?'mobile-open':''}`}><Link className="sidebar-brand" to={technician?'/queue':'/my-tickets'}><span className="brand-icon"><Headphones size={18}/></span><span>HelpDesk <b>360</b></span></Link><div className="nav-section-label">WORKSPACE</div><nav>{nav.map(([name,to,Icon])=><NavLink key={to} to={to} className={({isActive})=>`nav-link ${isActive?'active':''}`}><Icon size={17}/><span>{name}</span>{name==='Queue'&&<span className="nav-dot"/>}</NavLink>)}</nav><div className="sidebar-bottom"><div className="support-card"><div className="support-icon"><ShieldCheck size={17}/></div><div><b>Support team</b><span>Ready to help</span></div><span className="online-dot"/></div><div className="sidebar-version">HELPDESK 360 <span>·</span> v1.0</div></div></aside>
    {menuOpen&&<button className="scrim" aria-label="Close navigation" onClick={()=>setMenuOpen(false)}/>}
    <div className="main-column"><header className="topbar"><button className="icon-btn mobile-menu" aria-label="Open menu" onClick={()=>setMenuOpen(x=>!x)}><Menu size={19}/></button><div className="breadcrumbs"><span>Workspace</span><span className="crumb-sep">/</span><b>{pageTitle(location.pathname)}</b></div><div className="topbar-actions"><div className="api-state"><span className="online-dot"/> System operational</div><div className="topbar-divider"/><div className="notification-wrap"><button className="icon-btn" aria-label="Notifications" onClick={()=>{setNotificationOpen(x=>!x);markRead();}}><Bell size={18}/>{notifications.some(n=>!n.read_at)&&<i/>}</button>{notificationOpen&&<div className="notification-popover"><div className="popover-head"><b>Notifications</b><button className="icon-btn tiny" onClick={()=>setNotificationOpen(false)} aria-label="Close"><X size={15}/></button></div>{notifications.length?notifications.slice(0,8).map(n=><Link key={n.id} onClick={()=>setNotificationOpen(false)} to={ticketLink(n.ticket_id)} className="notification-item"><span className="notification-mark"><Activity size={14}/></span><span><b>Ticket #{n.ticket_id}</b><small>{n.message}</small><time>{relative(n.created_at)}</time></span></Link>):<p className="empty-mini">No notifications yet.</p>}</div>}</div><button className="profile-button" onClick={()=>setMenuOpen(false)}><span className="avatar">{user.display_name.split(' ').map(x=>x[0]).join('').slice(0,2)}</span><span className="profile-text"><b>{user.display_name}</b><small>{user.role}</small></span><ChevronDown size={15}/></button><button className="icon-btn logout-btn" aria-label="Log out" title="Log out" onClick={logout}><LogOut size={17}/></button></div></header>
      <main className="page-content"><Routes><Route path="/" element={<Navigate to={technician?'/dashboard':'/my-tickets'} replace/>}/><Route path="/new" element={<NewTicket/>}/><Route path="/my-tickets" element={<EmployeeOnly><TicketList mine/></EmployeeOnly>}/><Route path="/queue" element={<TechnicianOnly><Queue/></TechnicianOnly>}/><Route path="/dashboard" element={<TechnicianOnly><Dashboard/></TechnicianOnly>}/><Route path="/tickets/:id" element={<TicketDetail/>}/><Route path="*" element={<EmptyState title="Page not found" action={<Link className="button-link" to="/">Return to workspace</Link>}/>}/></Routes></main>
      <footer className="app-footer"><span>HelpDesk 360 <span className="footer-sep">/</span> IT support operations</span><button className="shortcut-button" onClick={()=>setShortcuts(true)}><CircleHelp size={14}/> Keyboard shortcuts <kbd>?</kbd></button></footer>
    </div>{shortcuts&&<div className="modal-scrim" onMouseDown={e=>e.target===e.currentTarget&&setShortcuts(false)}><section className="shortcuts-modal panel"><button className="icon-btn modal-close" onClick={()=>setShortcuts(false)} aria-label="Close shortcuts"><X size={18}/></button><div className="eyebrow">QUICK NAVIGATION</div><h2>Keyboard shortcuts</h2><div className="shortcut-row"><span>Focus search</span><kbd>/</kbd></div><div className="shortcut-row"><span>New ticket</span><kbd>N</kbd></div>{technician&&<><div className="shortcut-row"><span>Go to queue</span><kbd>G</kbd><kbd>Q</kbd></div><div className="shortcut-row"><span>Go to dashboard</span><kbd>G</kbd><kbd>D</kbd></div></>}<div className="shortcut-row"><span>Close dialog or menu</span><kbd>Esc</kbd></div></section></div>}
  </div>;
}
function Shell(){
  const {user,setUser,setOffline}=useAuth(),navigate=useNavigate(),location=useLocation(),notify=useToast();
  const [menuOpen,setMenuOpen]=useState(false),[profileOpen,setProfileOpen]=useState(false),[notificationOpen,setNotificationOpen]=useState(false),[notifications,setNotifications]=useState([]),[shortcuts,setShortcuts]=useState(false),[stats,setStats]=useState(null),[health,setHealth]=useState('checking');
  const profileRef=useRef(null),profileButtonRef=useRef(null),notificationRef=useRef(null);
  const technician=user.role==='technician';
  useEffect(()=>{setMenuOpen(false);setProfileOpen(false);setNotificationOpen(false);},[location.pathname]);
  useEffect(()=>{api('/notifications').then(x=>setNotifications(x.items)).catch(()=>{});},[user]);
  useEffect(()=>{let alive=true;const check=()=>api('/health').then(()=>{if(alive){setHealth('ok');setOffline(false);}}).catch(()=>{if(alive){setHealth('offline');setOffline(true);}});check();const timer=window.setInterval(check,30000);return()=>{alive=false;window.clearInterval(timer);};},[setOffline]);
  useEffect(()=>{if(profileOpen)api('/me/stats').then(setStats).catch(()=>setStats(null));},[profileOpen,user]);
  useEffect(()=>{if(profileOpen)requestAnimationFrame(()=>profileRef.current?.querySelector('[role="menuitem"]')?.focus());},[profileOpen]);
  useEffect(()=>{const outside=e=>{if(!profileRef.current?.contains(e.target))setProfileOpen(false);if(!notificationRef.current?.contains(e.target))setNotificationOpen(false);};document.addEventListener('mousedown',outside);return()=>document.removeEventListener('mousedown',outside);},[]);
  useEffect(()=>{const onKey=e=>{if(e.key==='Escape'){setShortcuts(false);setNotificationOpen(false);setProfileOpen(false);setMenuOpen(false);profileButtonRef.current?.focus();return;}if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))return;if(e.key==='?'){setShortcuts(x=>!x);return;}if(e.key==='/'){e.preventDefault();document.querySelector('[data-global-search]')?.focus();return;}if(e.key==='n'&&!technician){navigate('/new');return;}if(e.key==='g'){window.__helpdeskPrefix=true;window.setTimeout(()=>{window.__helpdeskPrefix=false;},900);return;}if(window.__helpdeskPrefix&&e.key==='q'&&technician)navigate('/queue');if(window.__helpdeskPrefix&&e.key==='d'&&technician)navigate('/dashboard');};window.addEventListener('keydown',onKey);return()=>window.removeEventListener('keydown',onKey);},[navigate,technician]);
  async function logout(){await send('/auth/logout','POST').catch(()=>{});setUser(null);setHealth('checking');}
  async function markAllRead(){try{await send('/notifications/read','POST',{all:true});setNotifications(items=>items.map(n=>({...n,read_at:n.read_at||new Date().toISOString()})));}catch(e){notify(e.message,'error');}}
  async function openNotification(item){if(!item.read_at){await send('/notifications/read','POST',{ids:[item.id]}).catch(()=>{});setNotifications(items=>items.map(n=>n.id===item.id?{...n,read_at:new Date().toISOString()}:n));}setNotificationOpen(false);navigate(ticketLink(item.ticket_id));}
  const nav=technician?[['Dashboard','/dashboard',Gauge],['Queue','/queue',ClipboardList]]:[['My tickets','/my-tickets',Ticket],['New ticket','/new',FilePlus2]];
  const menuKeyDown=e=>{if(!['ArrowDown','ArrowUp','Home','End'].includes(e.key))return;e.preventDefault();const items=[...e.currentTarget.querySelectorAll('[role="menuitem"]')];const index=items.indexOf(document.activeElement);const next=e.key==='Home'?0:e.key==='End'?items.length-1:e.key==='ArrowDown'?(index+1)%items.length:(index-1+items.length)%items.length;items[next]?.focus();};
  return <div className="app-shell">
    <aside className={`sidebar ${menuOpen?'mobile-open':''}`}><Link className="sidebar-brand" to={technician?'/queue':'/my-tickets'}><span className="brand-icon"><Headphones size={18}/></span><span>HelpDesk <b>360</b></span></Link><div className="nav-section-label">WORKSPACE</div><nav>{nav.map(([name,to,Icon])=><NavLink key={to} to={to} className={({isActive})=>`nav-link ${isActive?'active':''}`}><Icon size={17}/><span>{name}</span>{name==='Queue'&&<span className="nav-dot"/>}</NavLink>)}</nav><div className="sidebar-bottom"><div className="support-card"><div className="support-icon"><ShieldCheck size={17}/></div><div><b>Support team</b><span>Ready to help</span></div><span className="online-dot"/></div><div className="sidebar-version">HELPDESK 360 <span>·</span> v1.0</div></div></aside>
    {menuOpen&&<button className="scrim" aria-label="Close navigation" onClick={()=>setMenuOpen(false)}/>}
    <div className="main-column"><header className="topbar"><button className="icon-btn mobile-menu" aria-label="Open menu" aria-expanded={menuOpen} onClick={()=>setMenuOpen(x=>!x)}><Menu size={19}/></button>{!technician&&<Link className="employee-brand" to="/my-tickets">HelpDesk <b>360</b></Link>}<div className="breadcrumbs"><span>Workspace</span><span className="crumb-sep">/</span><b>{pageTitle(location.pathname)}</b></div>{!technician&&<nav className="employee-topnav"><NavLink to="/my-tickets">My tickets</NavLink><NavLink to="/new">New ticket</NavLink></nav>}<div className="topbar-actions"><div className={`api-state ${health==='offline'?'offline':''}`} role="status"><span className="online-dot"/>{health==='ok'?'Operational':health==='offline'?"Can't reach the server":'Checking…'}</div><div className="topbar-divider"/>
      <div className="notification-wrap" ref={notificationRef}><button className="icon-btn" aria-label="Notifications" aria-haspopup="menu" aria-expanded={notificationOpen} onClick={()=>setNotificationOpen(x=>!x)}><Bell size={18}/>{notifications.some(n=>!n.read_at)&&<i/>}</button>{notificationOpen&&<div className="notification-popover" role="menu"><div className="popover-head"><b>Notifications</b><button className="text-action" onClick={markAllRead} disabled={!notifications.some(n=>!n.read_at)}>Mark all as read</button><button className="icon-btn tiny" onClick={()=>setNotificationOpen(false)} aria-label="Close notifications"><X size={15}/></button></div>{notifications.length?notifications.map(n=><button key={n.id} role="menuitem" className={`notification-item ${n.read_at?'read':''}`} onClick={()=>openNotification(n)}><span className="notification-mark"><Activity size={14}/></span><span className="notification-content"><b>Ticket #{n.ticket_id}</b><small>{n.message}</small><time>{relative(n.created_at)}</time></span>{!n.read_at&&<i className="unread-dot" aria-label="Unread"/>}</button>):<p className="empty-mini">You’re all caught up.</p>}</div>}</div>
      <div className="user-menu-wrap" ref={profileRef}><button className="profile-button" ref={profileButtonRef} aria-haspopup="menu" aria-expanded={profileOpen} onClick={()=>setProfileOpen(x=>!x)}><span className="avatar">{user.display_name.split(' ').map(x=>x[0]).join('').slice(0,2)}</span><span className="profile-text"><b>{user.display_name}</b><small>{user.role}</small></span><ChevronDown size={15}/></button>{profileOpen&&<div className="user-menu" role="menu" onKeyDown={menuKeyDown}><div className="user-menu-identity"><span className="avatar">{user.display_name.split(' ').map(x=>x[0]).join('').slice(0,2)}</span><span><b>{user.display_name}</b><small>{user.username}</small></span><span className="role-chip">{user.role}</span></div><div className="user-menu-stats">{technician?<><div><b>{stats?.active??'—'}</b><span>Active assigned</span></div><div><b>{stats?.urgent??'—'}</b><span>Urgent assigned</span></div><div><b>{stats?.resolved_this_week??'—'}</b><span>Resolved this week</span></div></>:<><div><b>{stats?.open??'—'}</b><span>My open tickets</span></div><div><b>{stats?.waiting_on_it??'—'}</b><span>Waiting on IT</span></div></>}</div>{technician?<Link role="menuitem" to="/queue?assigned=me" onClick={()=>setProfileOpen(false)}>Assigned to me</Link>:<Link role="menuitem" to="/my-tickets" onClick={()=>setProfileOpen(false)}>My tickets</Link>}<button role="menuitem" onClick={()=>{setProfileOpen(false);setShortcuts(true);}}>Keyboard shortcuts</button><button role="menuitem" onClick={logout}><LogOut size={14}/> Log out</button></div>}</div>
      </div></header>
      <main className="page-content"><Routes><Route path="/" element={<Navigate to={technician?'/dashboard':'/my-tickets'} replace/>}/><Route path="/new" element={<EmployeeOnly><NewTicket/></EmployeeOnly>}/><Route path="/my-tickets" element={<EmployeeOnly><TicketList mine/></EmployeeOnly>}/><Route path="/queue" element={<TechnicianOnly><Queue/></TechnicianOnly>}/><Route path="/dashboard" element={<TechnicianOnly><Dashboard/></TechnicianOnly>}/><Route path="/tickets/:id" element={<TicketDetail/>}/><Route path="*" element={<EmptyState title="Page not found" action={<Link className="button-link" to="/">Return to workspace</Link>}/>}/></Routes></main>
      <footer className="app-footer"><span>HelpDesk 360 <span className="footer-sep">/</span> IT support operations</span><button className="shortcut-button" onClick={()=>setShortcuts(true)}><CircleHelp size={14}/> Keyboard shortcuts <kbd>?</kbd></button></footer>
    </div>{shortcuts&&<div className="modal-scrim" onMouseDown={e=>e.target===e.currentTarget&&setShortcuts(false)}><section className="shortcuts-modal panel"><button className="icon-btn modal-close" onClick={()=>setShortcuts(false)} aria-label="Close shortcuts"><X size={18}/></button><div className="eyebrow">QUICK NAVIGATION</div><h2>Keyboard shortcuts</h2><div className="shortcut-row"><span>Focus search</span><kbd>/</kbd></div>{!technician&&<div className="shortcut-row"><span>New ticket</span><kbd>N</kbd></div>}{technician&&<><div className="shortcut-row"><span>Go to queue</span><kbd>G</kbd><kbd>Q</kbd></div><div className="shortcut-row"><span>Go to dashboard</span><kbd>G</kbd><kbd>D</kbd></div></>}<div className="shortcut-row"><span>Close dialog or menu</span><kbd>Esc</kbd></div></section></div>}
  </div>;
}

function pageTitle(path){if(path.startsWith('/tickets/'))return 'Ticket details';return {'/dashboard':'Dashboard','/queue':'Support queue','/new':'New ticket','/my-tickets':'My tickets'}[path]||'Workspace';}
function EmployeeOnly({children}){return useAuth().user.role==='employee'?children:<Navigate to="/queue" replace/>;}
function TechnicianOnly({children}){return useAuth().user.role==='technician'?children:<Navigate to="/my-tickets" replace/>;}

function PageHeading({eyebrow,title,description,action}){return <div className="page-heading"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p className="muted">{description}</p></div>{action}</div>;}
function LoadingRows(){return <div className="skeleton-list" aria-label="Loading tickets">{[1,2,3,4].map(x=><div key={x} className="skeleton-row"><i/><i/><i/></div>)}</div>;}
function EmptyState({title,body='There is nothing here yet.',action}){return <div className="empty-state"><div className="empty-icon"><ClipboardList size={22}/></div><h3>{title}</h3><p>{body}</p>{action}</div>;}
function TicketRow({ticket,queue=false,onAssign,technicians=[],selected=false}){const {user}=useAuth();return <div className={`ticket-row ${ticket.status==='resolved'||ticket.status==='closed'?'is-done':''} ${selected?'keyboard-selected':''}`}><span className={`priority-rail ${ticket.priority}`}/><Link to={ticketLink(ticket.id)} className="ticket-id">#{ticket.id}</Link><Link to={ticketLink(ticket.id)} className="ticket-title"><span>{ticket.title}</span><small>{labels[ticket.category]}</small></Link><PriorityBadge priority={ticket.priority}/><StatusBadge status={ticket.status}/><div className="assignee-cell">{queue?<><select aria-label={`Assign ticket ${ticket.id}`} className={!ticket.assigned_to?'assign-select unassigned':''} value={ticket.assigned_to||''} onChange={e=>onAssign(ticket,e.target.value?Number(e.target.value):null)}><option value="">Unassigned</option>{technicians.map(t=><option key={t.id} value={t.id}>{t.display_name}</option>)}</select>{user.role==='technician'&&ticket.assigned_to!==user.username&&<button className="text-action assign-me" onClick={()=>{const t=technicians.find(x=>x.username===user.username);if(t)onAssign(ticket,t.id);}}>Assign to me</button>}</>:ticket.assigned_to?<span>{ticket.assigned_to_name||ticket.assigned_to}</span>:<span className="unassigned-text">Unassigned</span>}</div><div className="ticket-updated" title={fmtDate(ticket.updated_at)}><span>{relative(ticket.updated_at)}</span>{ticket.sla_overdue&&<span className="sla-flag">Overdue</span>}{ticket.is_stale&&<span className="stale-flag">Stale</span>}</div><Link className="row-open" to={ticketLink(ticket.id)} aria-label={`Open ticket ${ticket.id}`}>›</Link></div>;}
function TicketTable({items,queue,technicians,onAssign,selectedId}){return <><div className="table-head"><span>#</span><span>Ticket</span><span>Priority</span><span>Status</span><span>{queue?'Assigned to':'Technician'}</span><span>Updated</span><span/></div><div className="ticket-list">{items.map(t=><TicketRow key={t.id} ticket={t} queue={queue} technicians={technicians} onAssign={onAssign} selected={t.id===selectedId}/>)}</div></>;}

function EmployeeTicketCard({ticket}){const steps=['open','in-progress','resolved','closed'];const active=steps.indexOf(ticket.status);const assigned=ticket.assigned_to_name||ticket.assigned_to;const progress=['resolved','closed'].includes(ticket.status)?`${labels[ticket.status]} ${relative(ticket.updated_at)}`:ticket.status==='in-progress'&&assigned?`${assigned} is working on it`:assigned?`Assigned to ${assigned}`:'Waiting for a technician';return <Link className="employee-ticket-card" to={ticketLink(ticket.id)}><div className="employee-ticket-top"><span className="ticket-id">#{ticket.id}</span><span className="employee-ticket-badges"><PriorityBadge priority={ticket.priority}/><StatusBadge status={ticket.status}/></span></div><h2>{ticket.title}</h2><div className="mini-stepper">{steps.map((step,i)=><i key={step} className={i<=active?'reached':''} title={labels[step]}/>)}</div><div className="employee-ticket-bottom"><span>{progress}</span><time title={fmtDate(ticket.updated_at)}>{relative(ticket.updated_at)}</time></div></Link>;}

function TicketList({mine=false}){const [items,setItems]=useState(null),[stats,setStats]=useState(null),[error,setError]=useState('');const navigate=useNavigate(),{user}=useAuth();
  async function load(){setError('');try{const [tickets,summary]=await Promise.all([api('/tickets'),api('/me/stats')]);setItems(tickets.items);setStats(summary);}catch(e){setError(e.message);setItems([]);}}
  useEffect(()=>{load();},[]);
  return <><PageHeading eyebrow="HELP CENTER" title={`Hi ${user.display_name.split(' ')[0]}`} description="Your support requests and updates are all in one place." action={<button className="primary-btn" onClick={()=>navigate('/new')}><FilePlus2 size={16}/> New ticket</button>}/>
    <div className="employee-summary"><div><b>{stats?.open??'—'}</b><span>Open</span></div><div><b>{stats?.waiting_on_it??'—'}</b><span>Waiting on IT</span></div><div><b>{stats?.resolved??'—'}</b><span>Resolved</span></div></div>
    <section className="report-problem"><div><h2>Report a problem</h2><p>Choose a category to get started.</p></div><div className="category-tiles">{CATEGORIES.map((category,i)=>{const Icon=[Headphones,Activity,Command,LockKeyhole][i];return <Link key={category} to={`/new?category=${category}`}><Icon size={18}/><span>{labels[category]}</span><ChevronDown size={14}/></Link>;})}</div></section>
    <div className="page-toolbar"><div className="inline-title"><Ticket size={17}/><b>My requests</b><span className="count-pill">{items?.length??'—'}</span></div><button className="subtle-btn" onClick={load}><Activity size={15}/> Refresh</button></div><ErrorMessage>{error}</ErrorMessage>
    {items===null?<LoadingRows/>:items.length?<section className="employee-ticket-grid">{items.map(ticket=><EmployeeTicketCard key={ticket.id} ticket={ticket}/>)}</section>:<EmptyState title="No tickets yet" body="Tell the IT team what you need help with." action={<button className="primary-btn" onClick={()=>navigate('/new')}>Report a problem</button>}/>}
  </>;
}

function NewTicket(){const navigate=useNavigate(),notify=useToast(),[searchParams]=useSearchParams(),[form,setForm]=useState(()=>({title:'',description:'',category:CATEGORIES.includes(searchParams.get('category'))?searchParams.get('category'):'hardware',priority:'medium'})),[errors,setErrors]=useState({}),[pending,setPending]=useState(false),[error,setError]=useState(''),[created,setCreated]=useState(null),[similar,setSimilar]=useState([]),[suggestion,setSuggestion]=useState(null);
  const token=useMemo(()=>crypto.randomUUID(),[]);
  useEffect(()=>{const text=`${form.title} ${form.description}`.toLowerCase();let category=null,priority=null;if(/wifi|wi-fi|vpn|network|internet/.test(text))category='network';if(/locked out|password|mfa|account|sign in/.test(text))category='account-access';if(/license|software|application|app/.test(text))category='software';if(/laptop|keyboard|monitor|printer|hardware/.test(text))category='hardware';if(/cannot work|can't work|everyone|several people|blocked/.test(text))priority='high';if(/all users|entire office|company-wide/.test(text))priority='urgent';setSuggestion(category||priority?{category,priority}:null);},[form.title,form.description]);
  useEffect(()=>{if(form.title.trim().length<5)return;const timer=setTimeout(()=>api(`/tickets/similar?title=${encodeURIComponent(form.title.trim())}`).then(x=>setSimilar(x.items)).catch(()=>{}),400);return()=>clearTimeout(timer);},[form.title]);
  const set=(key,value)=>setForm(f=>({...f,[key]:value}));
  async function submit(e){e.preventDefault();const next={};if(!form.title.trim())next.title='Enter a title.';else if(form.title.length>150)next.title='Keep the title under 150 characters.';if(!form.description.trim())next.description='Describe the issue.';else if(form.description.length>5000)next.description='Keep the description under 5,000 characters.';setErrors(next);if(Object.keys(next).length)return;setPending(true);setError('');try{const ticket=await send('/tickets','POST',{...form,client_token:token});setCreated(ticket);notify(`Ticket #${ticket.id} submitted.`);}catch(err){setError(err.status===0?"Couldn't reach the server. Your ticket was not submitted.":err.message);}finally{setPending(false);}}
  if(created)return <section className="panel success-panel"><div className="success-mark"><Check size={24}/></div><div className="eyebrow">REQUEST SUBMITTED</div><h1>Ticket #{created.id} is in the queue</h1><p className="muted">Your request has been saved. You can follow its progress from My tickets.</p><div className="action-row"><button className="primary-btn" onClick={()=>navigate(ticketLink(created.id))}>View ticket</button><button className="secondary-btn" onClick={()=>navigate('/my-tickets')}>My tickets</button></div></section>;
  return <><PageHeading eyebrow="EMPLOYEE WORKSPACE" title="New ticket" description="Tell us what is happening and the support team will take it from there."/><form className="panel form-panel" onSubmit={submit} noValidate><div className="form-grid"><label className="field full-field">Title <span className={`counter ${form.title.length>=135?'warn':''}`}>{form.title.length}/150</span><input maxLength={150} value={form.title} onChange={e=>set('title',e.target.value)} aria-describedby={errors.title?'title-error':undefined} placeholder="e.g. Laptop will not start after update"/>{errors.title&&<small id="title-error" className="field-error">{errors.title}</small>}</label>
    <label className="field">Category<select value={form.category} onChange={e=>set('category',e.target.value)}>{CATEGORIES.map(c=><option key={c} value={c}>{labels[c]}</option>)}</select></label><label className="field">Priority<select value={form.priority} onChange={e=>set('priority',e.target.value)}>{PRIORITIES.map(p=><option key={p} value={p}>{labels[p]}</option>)}</select><small className="field-help">Urgent means work is blocked for several people.</small></label>
    <label className="field full-field">Description <span className={`counter ${form.description.length>=4500?'warn':''}`}>{form.description.length}/5000</span><textarea rows="7" maxLength={5000} value={form.description} onChange={e=>set('description',e.target.value)} aria-describedby={errors.description?'description-error':undefined} placeholder="What happened? When did it start? What have you tried?"/>{errors.description&&<small id="description-error" className="field-error">{errors.description}</small>}</label></div>
    {suggestion&&<div className="suggestion"><Sparkles size={16}/><span>Suggested: {suggestion.category?labels[suggestion.category]:labels[form.category]}{suggestion.priority?`, ${labels[suggestion.priority]}`:''}</span><button type="button" onClick={()=>{setForm(f=>({...f,...(suggestion.category?{category:suggestion.category}:{}),...(suggestion.priority?{priority:suggestion.priority}:{})}));setSuggestion(null);}}>Apply</button><button type="button" className="suggestion-dismiss" onClick={()=>setSuggestion(null)} aria-label="Dismiss suggestion"><X size={14}/></button></div>}
    {similar.length>0&&<div className="similar-warning"><Search size={16}/><div><b>You may already have an open ticket that looks similar.</b>{similar.slice(0,3).map(t=><Link key={t.id} to={ticketLink(t.id)}>#{t.id} {t.title}</Link>)}</div></div>}
    <ErrorMessage>{error}</ErrorMessage><div className="form-actions"><span className="muted">Your ticket is private to you and the IT support team.</span><button className="primary-btn" disabled={pending}>{pending?'Submitting…':'Submit ticket'}</button></div></form></>;
}

function Queue(){const [params,setParams]=useSearchParams(),[items,setItems]=useState(null),[urgentItems,setUrgentItems]=useState([]),[technicians,setTechnicians]=useState([]),[viewCounts,setViewCounts]=useState({}),[selectedId,setSelectedId]=useState(null),[error,setError]=useState(''),notify=useToast(),{user}=useAuth();
  const status=params.get('status')||'',priority=params.get('priority')||'',category=params.get('category')||'',assigned=params.get('assigned')||'',q=params.get('q')||'';
  const dashboardKeys=['status','active','overdue','assigned','priority','category'];
  const hasDashboardFilters=dashboardKeys.some(key=>params.has(key));
  const filterDescription=[status&&`Status ${status.split(',').map(s=>labels[s]||s).join(', ')}`,priority&&`Priority ${labels[priority]}`,category&&`Category ${labels[category]}`,params.get('active')&&'Active',params.get('overdue')&&'Overdue',assigned&&(assigned==='me'?'Assigned to me':assigned==='unassigned'?'Unassigned':`Assigned to ${assigned}`)].filter(Boolean).join(' · ');
  async function load(){setError('');try{const query=params.toString();const [data,people,urgentData]=await Promise.all([api(`/tickets${query?`?${query}`:''}`),api('/users?role=technician'),api('/tickets?priority=urgent&active=1')]);setItems(data.items);setTechnicians(people.items);setUrgentItems(urgentData.items);}catch(e){setError(e.message);setItems([]);}}
  async function loadViewCounts(){try{const results=await Promise.all(QUEUE_VIEWS.map(view=>api(`/tickets?${view.query}`)));setViewCounts(Object.fromEntries(QUEUE_VIEWS.map((view,i)=>[view.label,results[i].items.length])));}catch{setViewCounts({});}}
  useEffect(()=>{load();},[params.toString()]);
  useEffect(()=>{loadViewCounts();},[params.toString()]);
  useEffect(()=>{if(!items?.length)return;const onKey=e=>{if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))return;if(!['j','k','Enter','a'].includes(e.key))return;e.preventDefault();const current=items.findIndex(item=>item.id===selectedId);if(e.key==='j'||e.key==='k'){const index=current<0?0:(current+(e.key==='j'?1:-1)+items.length)%items.length;setSelectedId(items[index].id);return;}const chosen=items[current<0?0:current];if(!chosen)return;if(e.key==='Enter')navigate(ticketLink(chosen.id));if(e.key==='a'){const mine=technicians.find(t=>t.username===user.username);if(mine)assign(chosen,mine.id);}};window.addEventListener('keydown',onKey);return()=>window.removeEventListener('keydown',onKey);},[items,selectedId,technicians,user.username]);
  useEffect(()=>{document.querySelector('.keyboard-selected')?.scrollIntoView({block:'nearest'});},[selectedId]);
  const navigate=useNavigate();
  const urgent=[...urgentItems].sort((a,b)=>a.created_at.localeCompare(b.created_at));
  async function assign(ticket,assigned_to){try{await send(`/tickets/${ticket.id}`,'PATCH',{assigned_to});notify(assigned_to?`Ticket #${ticket.id} assigned.`:`Ticket #${ticket.id} unassigned.`);load();loadViewCounts();}catch(e){notify(e.message,'error');}}
  function update(key,value){const next=new URLSearchParams(params);if(value)next.set(key,value);else next.delete(key);setParams(next);}
  function clear(){setParams({});}
  return <><PageHeading eyebrow="TECHNICIAN WORKSPACE" title="Support queue" description="Prioritize incoming work, assign ownership and keep requests moving." action={<Link to="/dashboard" className="secondary-btn"><Gauge size={16}/> Dashboard</Link>}/>
    <nav className="queue-view-tabs" aria-label="Saved queue views">{QUEUE_VIEWS.map(view=><button key={view.label} className={params.toString()===view.query.replace('%2C',',')||params.toString()===view.query?'selected':''} onClick={()=>setParams(new URLSearchParams(view.query))}>{view.label}<span>{viewCounts[view.label]??'—'}</span></button>)}</nav>
    {hasDashboardFilters&&<div className="drill-toolbar"><Link to="/dashboard" className="text-action">← Back to dashboard</Link><button className="filter-chip selected" onClick={clear}>Filtered: {filterDescription} ({items?.length??'…'}) <span aria-hidden="true">×</span></button></div>}
    {urgent.length>0&&<section className="urgent-strip"><div className="urgent-icon"><Activity size={18}/></div><div className="urgent-strip-heading"><b>Urgent now</b><span>{urgent.length} active {urgent.length===1?'ticket':'tickets'} · oldest first</span></div><div className="urgent-items">{urgent.slice(0,4).map(t=><Link key={t.id} to={ticketLink(t.id)}><span>#{t.id}</span> {t.title}<small>{relative(t.created_at)}</small></Link>)}</div></section>}
    <section className="panel queue-panel"><div className="queue-filters"><label className="search-box"><Search size={16}/><input data-global-search value={q} onChange={e=>update('q',e.target.value)} placeholder="Search ticket titles"/></label><select aria-label="Filter by status" value={STATUSES.includes(status)?status:''} onChange={e=>update('status',e.target.value)}><option value="">All statuses</option>{STATUSES.map(s=><option key={s} value={s}>{labels[s]}</option>)}</select><select aria-label="Filter by priority" value={priority} onChange={e=>update('priority',e.target.value)}><option value="">All priorities</option>{PRIORITIES.map(p=><option key={p} value={p}>{labels[p]}</option>)}</select><select aria-label="Filter by category" value={category} onChange={e=>update('category',e.target.value)}><option value="">All categories</option>{CATEGORIES.map(c=><option key={c} value={c}>{labels[c]}</option>)}</select><div className="toggle-filters"><button className={assigned==='unassigned'?'filter-chip selected':'filter-chip'} onClick={()=>update('assigned',assigned==='unassigned'?'':'unassigned')}>Unassigned</button><button className={assigned==='me'?'filter-chip selected':'filter-chip'} onClick={()=>update('assigned',assigned==='me'?'':'me')}>Mine</button></div></div>
      <div className="queue-summary"><div className="inline-title"><ClipboardList size={16}/><b>All tickets</b><span className="count-pill">{items?.length??'—'}</span></div><button className="subtle-btn" onClick={()=>{load();loadViewCounts();}}><Activity size={15}/> Refresh</button></div><ErrorMessage>{error}</ErrorMessage>
      {items===null?<LoadingRows/>:items.length?<div className="table-scroll"><TicketTable items={items} queue technicians={technicians} onAssign={assign} selectedId={selectedId}/></div>:<EmptyState title={params.size?'No tickets match these filters.':'No tickets yet.'} body={params.size?'Try adjusting your search or filters.':'New employee requests will appear here.'} action={params.size?<button className="secondary-btn" onClick={clear}>Clear filters</button>:undefined}/>}
    </section></>;
}

function Metric({label,value,icon,accent,how,sub,to,split}){const content=<><div className="metric-top"><span>{label}</span><span className="metric-icon">{icon}</span></div><strong>{value}</strong>{sub&&<small>{sub}</small>}</>;const card=<article className={`metric-card ${accent||''} ${to?'is-drillable':''}`}>{to?<Link className="metric-main" to={to}>{content}</Link>:content}<How>{how}</How></article>;return split?<div className="metric-drill-wrap">{card}<div className="completed-split-links">{split}</div></div>:card;}
function BarList({title,items,total}){return <section className="panel chart-panel"><div className="panel-title"><h2>{title}</h2><span>All tickets</span></div>{items.length===0?<p className="empty-chart">No tickets yet.</p>:items.map(item=><Link className="bar-row dashboard-drill" to={filterLink(item.filter)} key={item.name}><span>{item.name}</span><div className="bar-track"><i style={{width:`${total?Math.max(2,item.value/total*100):0}%`}}/></div><b>{item.value}</b></Link>)}</section>;}
function Dashboard(){const [data,setData]=useState(null),[error,setError]=useState('');
  async function load(){setError('');try{setData(await api('/dashboard'));}catch(e){setError(e.message);}}
  useEffect(()=>{load();},[]);
  if(!data)return <><PageHeading eyebrow="TECHNICIAN WORKSPACE" title="Dashboard" description="A live view of current support demand and workload." action={<button className="subtle-btn" onClick={load}><Activity size={15}/> Refresh</button>}/>{error&&<ErrorMessage>{error}</ErrorMessage>}<LoadingRows/></>;
  const total=data.status.open+data.status['in-progress']+data.status.resolved+data.status.closed;
  const priorities=data.by_priority.items.map(x=>({name:labels[x.priority],value:x.count,filter:x.filter}));
  const categories=data.by_category.items.map(x=>({name:labels[x.category],value:x.count,filter:x.filter}));
  const maxDay=Math.max(1,...data.created_last_7_days.items.map(x=>x.count));
  return <><PageHeading eyebrow="TECHNICIAN WORKSPACE" title="Dashboard" description="A live view of current support demand and workload." action={<button className="subtle-btn" onClick={load}><Activity size={15}/> Refresh</button>}/>{error&&<ErrorMessage>{error}</ErrorMessage>}
    {data.empty&&<div className="info-banner"><CircleHelp size={17}/> No tickets yet. Dashboard values are zero until tickets are submitted.</div>}
    <section className="urgent-metric"><div className="urgent-metric-icon"><Activity size={19}/></div><div><Link className="urgent-metric-count dashboard-drill" to={filterLink(data.urgent_active.filter)}><span>URGENT ACTIVE</span><strong>{data.urgent_active.count}</strong></Link><How>{data.urgent_active.how}</How></div><p>Needs attention first</p></section>
    <div className="metrics-grid"><Metric label="Open" value={data.status.open} icon={<Circle size={17}/>} to={filterLink(data.status.filters.open)} how="tickets.status = 'open'. Source: shared ticket filter builder."/><Metric label="In progress" value={data.status['in-progress']} icon={<CircleDot size={17}/>} to={filterLink(data.status.filters['in-progress'])} how="tickets.status = 'in-progress'. Source: shared ticket filter builder."/><Metric label="Unassigned active" value={data.unassigned_active.count} icon={<UserRound size={17}/>} to={filterLink(data.unassigned_active.filter)} how={data.unassigned_active.how}/><Metric label="Completed" value={data.completed.resolved+data.completed.closed} icon={<Check size={17}/>} sub={`${data.completed.resolved} resolved · ${data.completed.closed} closed`} to={filterLink(data.completed.filter)} split={<><Link to={filterLink(data.completed.resolved_filter)}>Resolved</Link><Link to={filterLink(data.completed.closed_filter)}>Closed</Link></>} how={data.completed.how}/><Metric label="Overdue" value={data.overdue.count} icon={<Clock3 size={17}/>} to={filterLink(data.overdue.filter)} accent="metric-warning" how={data.overdue.how}/><Metric label="Average resolution" value={fmtDuration(data.average_resolution_hours.value)} icon={<Clock3 size={17}/>} sub={data.average_resolution_hours.count?`from ${data.average_resolution_hours.count} tickets`:'from 0 tickets'} how={data.average_resolution_hours.how}/><Metric label="Employee rating" value={data.ratings.average??'—'} icon={<Sparkles size={17}/>} sub={data.ratings.count?`from ${data.ratings.count} ${data.ratings.count===1?'rating':'ratings'}`:'No ratings yet'} how={data.ratings.how}/></div>
    <div className="charts-grid"><section className="panel chart-panel workload-panel"><div className="panel-title"><h2>Technician workload</h2><span>Current assignment</span></div>{data.by_technician.items.length?data.by_technician.items.map(t=><Link className="workload-row dashboard-drill" to={filterLink({assigned:t.username})} key={t.id}><div className="workload-name"><span className="avatar small">{t.display_name.split(' ').map(x=>x[0]).join('')}</span><b>{t.display_name}</b><span className="muted">{t.active} active · {t.completed} completed</span></div><div className="workload-bars"><i title={`${t.active} active`} style={{width:`${total?Math.max(t.active?2:0,t.active/total*100):0}%`}}/><i title={`${t.completed} completed`} style={{width:`${total?Math.max(t.completed?2:0,t.completed/total*100):0}%`}}/></div></Link>):<p className="empty-chart">No technicians available.</p>}<How>{data.by_technician.how}</How></section>
      <BarList title="Tickets by priority" items={priorities} total={total}/><BarList title="Tickets by category" items={categories} total={total}/>
      <section className="panel chart-panel week-panel"><div className="panel-title"><h2>Created in the last 7 days</h2><span>UTC dates</span></div><div className="week-bars">{Array.from({length:7},(_,i)=>{const day=new Date(Date.now()-(6-i)*86400000).toISOString().slice(0,10);const item=data.created_last_7_days.items.find(x=>x.day===day);const value=item?.count||0;return <div className="week-day" key={day}><b>{value}</b><i style={{height:`${Math.max(3,value/maxDay*100)}%`}}/><span>{new Intl.DateTimeFormat(undefined,{weekday:'short',timeZone:'UTC'}).format(new Date(`${day}T12:00:00Z`))}</span></div>})}</div><How>{data.created_last_7_days.how}</How></section>
    </div>
  </>;
}

function ConversationItem({item,ticket,technicians}){
  if(item.threadType==='history'){
    const title=item.event==='created'?'Ticket submitted':item.event==='status_change'?`Status changed to ${labels[item.to_value]||item.to_value}`:'Assignment updated';
    const assigned=item.to_assignee||technicians.find(t=>String(t.id)===item.to_value)?.display_name||ticket.assigned_to_name||'technician';
    const detail=item.event==='assignment'?`${item.from_value?'Assigned technician updated':'Ticket assigned'}${item.to_value?' to '+assigned:' · unassigned'}`:`by ${item.changed_by_name||item.changed_by}`;
    return <article className="comment thread-event" key={item.key}><div className="comment-head"><b>{title}</b><span className="role-chip">Activity</span><time>{fmtDate(item.created_at)}</time></div><p>{detail}</p></article>;
  }
  return <article className={`comment ${item.kind||'reply'}`} key={item.key}><div className="comment-head"><b>{item.author_name}</b><span className="role-chip">{item.kind==='internal_note'?'Internal note':item.kind==='resolution'?'Resolution summary':item.author_role}</span><time>{fmtDate(item.created_at)}</time></div>{item.kind==='internal_note'&&<small className="internal-note-label">Only visible to the support team</small>}<p>{item.body}</p></article>;
}

function TicketDetail(){const {id}=useParams(),{user}=useAuth(),notify=useToast(),[ticket,setTicket]=useState(null),[technicians,setTechnicians]=useState([]),[error,setError]=useState(''),[busy,setBusy]=useState(false),[comment,setComment]=useState(''),[commentKind,setCommentKind]=useState('reply'),[resolveOpen,setResolveOpen]=useState(false),[resolutionNote,setResolutionNote]=useState(''),[rating,setRating]=useState(5),[ratingComment,setRatingComment]=useState(''),[claimedByMe,setClaimedByMe]=useState(false),claimAttempted=useRef(false);
  async function load(){setError('');try{const x=await api(`/tickets/${id}`);setTicket(x);if(user.role==='technician')setTechnicians((await api('/users?role=technician')).items);}catch(e){setError(e.message);}}
  useEffect(()=>{claimAttempted.current=false;setClaimedByMe(false);load();},[id]);
  useEffect(()=>{if(user.role!=='technician'||!ticket||claimAttempted.current||ticket.assigned_to||!['open','in-progress'].includes(ticket.status))return;claimAttempted.current=true;send(`/tickets/${id}/claim`,'POST',{}).then(claimed=>{setTicket(claimed);setClaimedByMe(true);notify('Assigned to you.','success',{label:'Undo',onClick:async()=>{try{await send(`/tickets/${id}`,'PATCH',{assigned_to:null});setTicket(await api(`/tickets/${id}`));setClaimedByMe(false);notify('Assignment undone.');}catch(e){notify(e.message,'error');}}});}).catch(async e=>{if(e.status===409){try{setTicket(await api(`/tickets/${id}`));}catch{}notify(e.message,'error');}});},[ticket?.id,user.role,id,notify]);
  async function update(body){setBusy(true);try{await send(`/tickets/${id}`,'PATCH',body);notify('Ticket updated.');await load();return true;}catch(e){notify(e.message,'error');return false;}finally{setBusy(false);}}
  async function addComment(e){e.preventDefault();if(!comment.trim())return;setBusy(true);try{await send(`/tickets/${id}/comments`,'POST',{body:comment,kind:commentKind});setComment('');notify(commentKind==='internal_note'?'Internal note added.':'Reply sent.');await load();}catch(e){notify(e.message,'error');}finally{setBusy(false);}}
  async function resolveTicket(e){e.preventDefault();if(resolutionNote.trim().length<10||resolutionNote.trim().length>1000)return;if(await update({status:'resolved',resolution_note:resolutionNote.trim()})){setResolveOpen(false);setResolutionNote('');}}
  async function rate(e){e.preventDefault();setBusy(true);try{await send(`/tickets/${id}/rating`,'POST',{rating:Number(rating),comment:ratingComment});notify('Rating submitted.');await load();}catch(e){notify(e.message,'error');}finally{setBusy(false);}}
  if(error)return <><PageHeading eyebrow={`TICKET #${id}`} title="Ticket details" description="Review the request and its progress."/><section className="panel"><ErrorMessage>{error}</ErrorMessage><Link className="secondary-btn" to={user.role==='technician'?'/queue':'/my-tickets'}>Back to tickets</Link></section></>;
  if(!ticket)return <LoadingRows/>;
  const next={open:'in-progress','in-progress':'resolved',resolved:'closed'}[ticket.status];const steps=['open','in-progress','resolved','closed'];const conversation=[...ticket.history.map(h=>({...h,threadType:'history',key:`history-${h.id}`,created_at:h.changed_at})),...ticket.comments.map(c=>({...c,threadType:'comment',key:`comment-${c.id}`}))].sort((a,b)=>Date.parse(a.created_at)-Date.parse(b.created_at));
  return <><div className="detail-back"><Link to={user.role==='technician'?'/queue':'/my-tickets'}>‹ Back to {user.role==='technician'?'queue':'my tickets'}</Link></div><div className="detail-heading"><div><div className="eyebrow">TICKET #{ticket.id}</div><h1>{ticket.title}</h1><div className="badge-row"><PriorityBadge priority={ticket.priority}/><StatusBadge status={ticket.status}/><span className="category-label">{labels[ticket.category]}</span>{['open','in-progress'].includes(ticket.status)&&(ticket.sla_overdue?<span className="sla-flag">Overdue</span>:<span className="sla-timer">SLA due {fmtDate(ticket.sla_due_at)}</span>)}</div></div><span className="created-on">Created {fmtDate(ticket.created_at)}</span></div>
    <div className="detail-layout"><div className="detail-main"><section className="panel progress-panel"><div className="panel-title"><h2>Progress</h2><span>Updated {relative(ticket.updated_at)}</span></div><div className="progress-steps">{steps.map((s,i)=>{const active=steps.indexOf(ticket.status)>=i;const event=ticket.history.filter(h=>h.event==='status_change'&&h.to_value===s).at(-1);return <div key={s} className={`progress-step ${active?'reached':''}`}><span className="step-node">{active?<Check size={13}/>:i+1}</span><b>{labels[s]}</b><small>{s==='open'?fmtDate(ticket.created_at):event?fmtDate(event.changed_at):'Waiting'}</small></div>})}</div></section>
      <section className="panel description-panel"><div className="panel-title"><h2>Request description</h2><span>{ticket.description.length} characters</span></div><p className="ticket-description">{ticket.description}</p></section>
      <section className="panel comments-panel"><div className="panel-title"><h2>Conversation</h2><span>{conversation.length}</span></div>{conversation.length?conversation.map(item=><ConversationItem key={item.key} item={item} ticket={ticket} technicians={technicians}/>):<p className="empty-inline">No updates yet.</p>}{user.role==='technician'&&<div className="composer-tabs"><button type="button" className={commentKind==='reply'?'selected':''} onClick={()=>setCommentKind('reply')}>Reply to employee</button><button type="button" className={commentKind==='internal_note'?'selected':''} onClick={()=>setCommentKind('internal_note')}>Internal note</button></div>}{commentKind==='internal_note'&&user.role==='technician'&&<p className="internal-note-label">Only visible to the support team</p>}<form className={`comment-form ${commentKind==='internal_note'?'internal-composer':''}`} onSubmit={addComment}><div className="composer-input"><textarea value={comment} onChange={e=>setComment(e.target.value)} maxLength={2000} onKeyDown={e=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();e.currentTarget.form?.requestSubmit();}}} placeholder={commentKind==='internal_note'?'Write an internal note…':'Reply to the employee…'} aria-label={commentKind==='internal_note'?'Internal note':'Reply to employee'}/><small className="character-count">{comment.length}/2000 · Ctrl+Enter to send</small></div><button className="primary-btn" disabled={busy||!comment.trim()}>{busy?'Sending…':commentKind==='internal_note'?'Add internal note':'Send reply'}</button></form>{user.role==='technician'&&<div className="quick-replies">{['Please restart and tell me if it persists','I need more details: when did this start?','I’ll start a remote session with you shortly','Please try again now and confirm'].map(text=><button key={text} type="button" onClick={()=>{setCommentKind('reply');setComment(text);}}>{text}</button>)}</div>}</section>
      {user.role==='employee'&&['resolved','closed'].includes(ticket.status)&&!ticket.rating&&<section className="panel rating-panel"><h2>How did we do?</h2><form onSubmit={rate}><label>Rating<select value={rating} onChange={e=>setRating(e.target.value)}>{[5,4,3,2,1].map(n=><option value={n} key={n}>{n} — {['','Poor','Fair','Good','Very good','Excellent'][n]}</option>)}</select></label><label>Optional comment<input value={ratingComment} maxLength={500} onChange={e=>setRatingComment(e.target.value)}/></label><button className="secondary-btn" disabled={busy}>Submit rating</button></form></section>}
      {ticket.rating&&user.role==='technician'&&<section className="panel rating-panel"><h2>Employee rating</h2><p>{ticket.rating}/5{ticket.rating_comment?` · ${ticket.rating_comment}`:''}</p></section>}
    </div><aside className="detail-side"><section className="panel details-card"><div className="eyebrow">REQUEST DETAILS</div><dl><dt>Reported by</dt><dd>{ticket.reported_by_name||ticket.reported_by}</dd><dt>Assigned technician</dt><dd>{ticket.assigned_to_name||ticket.assigned_to||<span className="unassigned-text">Unassigned</span>}</dd><dt>Priority</dt><dd><PriorityBadge priority={ticket.priority}/></dd><dt>Category</dt><dd>{labels[ticket.category]}</dd><dt>Created</dt><dd>{fmtDate(ticket.created_at)}</dd><dt>Last updated</dt><dd>{fmtDate(ticket.updated_at)}</dd></dl>
      {user.role==='technician'&&<div className="technician-controls"><label>Assign technician<select value={technicians.find(t=>t.username===ticket.assigned_to)?.id||''} onChange={e=>update({assigned_to:e.target.value?Number(e.target.value):null})} disabled={busy||!technicians.length}><option value="">Unassigned</option>{technicians.map(t=><option key={t.id} value={t.id}>{t.display_name}</option>)}</select>{!technicians.length&&<small>No technicians available.</small>}</label>{next&&<button className="primary-btn full" disabled={busy} onClick={()=>next==='resolved'?setResolveOpen(true):update({status:next})}>{next==='in-progress'?'Start work':next==='resolved'?'Resolve ticket':'Close ticket'}</button>}</div>}</section><div className="side-note"><ShieldCheck size={16}/><span>Only you and the IT support team can view this ticket.</span></div></aside></div>
    {resolveOpen&&<div className="modal-scrim" onMouseDown={e=>e.target===e.currentTarget&&setResolveOpen(false)}><form className="panel resolve-dialog" onSubmit={resolveTicket}><button type="button" className="icon-btn modal-close" onClick={()=>setResolveOpen(false)} aria-label="Close resolve dialog"><X size={18}/></button><div className="eyebrow">RESOLVE TICKET</div><h2>What fixed the issue?</h2><p className="muted">Add a short resolution summary for the employee.</p><label>Resolution summary<textarea autoFocus required minLength={10} maxLength={1000} value={resolutionNote} onChange={e=>setResolutionNote(e.target.value)} placeholder="Describe the fix and outcome."/></label><small className="character-count">{resolutionNote.length}/1000</small><div className="form-actions"><button type="button" className="secondary-btn" onClick={()=>setResolveOpen(false)}>Cancel</button><button className="primary-btn" disabled={busy||resolutionNote.trim().length<10}>Resolve ticket</button></div></form></div>}
  </>;
}
